"""Reviewer-authored judgments. Generates only external_review artifacts."""
import json, csv, hashlib, subprocess
from pathlib import Path
from collections import Counter
R=Path(__file__).resolve().parents[1]; O=R/'external_review'
def load(p): return json.loads((R/p).read_text())
def write(p,s): (O/p).write_text(s+'\n')
def js(p,x): write(p,json.dumps(x,ensure_ascii=False,indent=2))
def table(rows):
    keys=list(rows[0]); return '| '+' | '.join(keys)+' |\n|'+ '|'.join(['---']*len(keys))+'|\n'+'\n'.join('| '+' | '.join(str(r[k]).replace('|','/').replace('\n',' ') for k in keys)+' |' for r in rows)
def csvout(p,rows):
    with (O/p).open('w') as f:
        w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)

# Each entry is a judgment, not a replacement of the internal statement.
specs=[
('MAJOR','final_synthesis.md: author/reviewer scope','RQ-11.01; RQ-12.01',[112,159,271,454,460,533,534,535,537], 'La reconstruction conditionnelle atténue des généralisations explicites.', 'Le manuscrit affirme une dégradation systématique, des limites générales à la croissance et des jugements sectoriels/politiques. Les exemples de services productifs p159/271 empêchent une exclusion sectorielle simple, sans effacer p534.', 'Séparer AUTHOR_CLAIMED_GENERALITY et REVIEWER_SUPPORTED_SCOPE; conserver les tensions sectorielles et normatives.', 'SYNTHESIS_TOO_WEAK','PARTIALLY_RESOLVED_BY_CORPUS'),
('MAJOR','GDP=K W; SYN-11','CPC-0127; RQ-08.01; RQ-09.03',[199,205,420,529,537,559], 'Le raccord comptable au PIB précède et dépasse le problème de stabilité de K.', 'P559 identifie PIB et Money dépensé; gain de pouvoir d’achat, prix total et valeur ajoutée ne sont pas automatiquement la même grandeur. Le contre-exemple brut 100+150=250 contre VA=150 est conditionnel: p205 exige précisément la valeur ajoutée, ce qui peut éviter ce double compte.', 'Définir flux par période, frontière nette, réemploi des paiements et prix nominal/réel avant de tester K. Ne pas attribuer au corpus un double compte inévitable.', 'SYNTHESIS_TOO_WEAK','PARTIALLY_RESOLVED_BY_CORPUS'),
('MAJOR','Money: référent, signe et origine','CPC-0010; CPC-0015; CPC-0043; CPC-0045; RQ-06.04',[15,19,204,205,206,207,455,467], 'Une variable unique mélange solde, gain, potentiel et transfert orienté.', 'M=nu, gain budgétaire p204, primitive négative p207 et somme cinétique/potentielle p467 ne partagent pas nécessairement origine et référent. Le cas numérique 1 contre −1 ne constitue une incompatibilité que si on impose ces référents identiques.', 'Introduire un dictionnaire explicite M_solde, deltaM_gain, M_cinétique et transfert orienté, comme reconstruction du reviewer, non correction silencieuse du manuscrit.', 'SYNTHESIS_FAITHFUL','PARTIALLY_RESOLVED_BY_CORPUS'),
('MAJOR','Core Law: dérivation et inversion','RQ-08.01; RQ-05.03',[285,299,301,303], 'Les limites invoquées ne justifient pas la dérivée; une inversion imprimée est incorrecte.', 'U/ΔF à U fixe ne tend pas vers dU/dF. Pour Fp=rU, F=rU/p, non (p/r)U. Inspection visuelle p303 confirme la disposition. P301 autorise une hypothèse simplificatrice: la relation peut être postulée, pas ainsi démontrée.', 'Distinguer loi proposée, dérivation non établie et erreur algébrique locale; préserver le modèle postulé sous conditions.', 'SYNTHESIS_FAITHFUL','PARTIALLY_RESOLVED_BY_CORPUS'),
('MODERATE','SYN-07: moyenne puis carré','RQ-08.02',[538,559], 'Le test de moyenne pondérée de K ne couvre pas le passage de moyenne des vitesses au carré.', 'Avec cp=2, les vitesses 1 et 3 donnent moyenne de T=5, contre 4 pour le carré de la moyenne; 2 et 2 donnent 4 avec la même moyenne. Le terme de variance disparaît dans la substitution.', 'Ajouter une condition sur la dispersion ou conserver les seconds moments. Un K ajusté peut absorber ce terme sans devenir structurellement constant.', 'SYNTHESIS_TOO_STRONG','UNRESOLVED'),
('MODERATE','VAR-16 energy','RQ-09.02', [455,456,559], 'DIRECTLY_OBSERVABLE est trop fort pour la série primaire par substitution.', 'La série indépendante du PIB utilise des conventions de conversion de l’électricité non fossile. Son acquisition est épinglée à une version; la reproductibilité L5 peut être conservée, pas le caractère directement mesuré de toute la grandeur.', 'Conserver L5 pour les données reproductibles; classer la quantité harmonisée DERIVABLE_FROM_OBSERVABLES avec hypothèses et méthode.', 'SYNTHESIS_TOO_STRONG','RESOLVED_BY_DATA_DOCUMENTATION'),
('MODERATE','Variables: Utility, dommage, coût','RQ-05.03; RQ-11.01; RQ-05.01',[108,109,112,349,386], 'Le niveau du concept cible est parfois confondu avec celui d’un proxy candidat.', 'Qualité technique ou classement ordinal ne mesurent pas les ratios de Utility; énergie et matières sont des pressions, pas une fonction de dommage. Inversement un coût comptable peut avoir une procédure L3 même si le proxy sectoriel retenu est L2.', 'Séparer maturité du concept, disponibilité des données et validité de correspondance. Utility/dommage cibles restent L1 tant que cette correspondance manque; proxies candidats L2.', 'SYNTHESIS_TOO_STRONG','UNRESOLVED'),
('MODERATE','Traceabilité sémantique et verify_synthesis','RQ-12.01',[], 'Existence de source et contrôle de structure ne vérifient pas son implication.', 'Deux mutations uniquement en mémoire sont acceptées: causalité monétaire générale erronée, puis README.md comme source existante sans rapport. Cela démontre une limite du validateur, pas que toutes les conclusions actuelles sont erronées.', 'Ajouter passages précis et rôle de chaque preuve; conserver revue humaine et cas négatifs. Ne pas compter les PASS comme confirmations économiques.', 'SYNTHESIS_FAITHFUL','UNRESOLVED'),
('MODERATE','CPC-0016: EMPIRICALLY_COMPATIBLE','CPC-0016; RQ-09.03',[21,455,456], 'La compatibilité du voisinage empirique est attribuée au claim complet.', 'Les associations énergie/PIB et le cas coût/prix ne mesurent pas indépendamment Work→u→Money. Le texte prudent ne suffit pas à corriger la portée de l’étiquette machine.', 'NOT_IDENTIFIED pour la chaîne complète; compatibilité descriptive seulement pour sous-relations identifiées et non discriminantes.', 'SYNTHESIS_TOO_STRONG','UNRESOLVED'),
('MODERATE','+78%: portée revendiquée','CPC-0035; RQ-04.04',[32,196,197,198,207], 'Le résultat arithmétique limité ne restitue pas à lui seul la généralité revendiquée.', 'P32 généralise aux Products et aux lieux/époques, avec prémisses d’homogénéité. (8/6)^2−1 est reproductible; cette opération n’établit ni homogénéité interproduits ni énergie économique indépendante.', 'Conserver ARITHMETICALLY_REPRODUCED et ASSUMPTION_DEPENDENT, en citant aussi la revendication universelle et son absence de test indépendant.', 'SYNTHESIS_TOO_WEAK','UNRESOLVED'),
('MINOR','Citations CORE tronquées','CPC-0041; CPC-0048',[35,185], 'Les citations isolées omettent une partie du contraste nécessaire.', 'Le voisinage p35 ajoute Cash au Product; p185 précise le référent des actifs et de Money. Les citations ne sont pas inventées, mais leur contexte fait partie de la preuve.', 'Étendre les extraits associés sans changer les IDs ni le sens du claim.', 'SYNTHESIS_FAITHFUL','RESOLVED_BY_CORPUS'),
('NOTE','CC-03: attribution de la contribution','RQ-05.03',[109,349,386], 'Un diagnostic métrologique du reviewer ne doit pas devenir une innovation attribuée à l’auteur.', 'L’analyse interne le signale déjà. Les exigences d’échelles ont un précédent méthodologique explicite; le diagnostic appliqué aux formules reste utile.', 'Étiqueter CONTRIBUTION_OF_REVIEW pour le diagnostic et distinctement les opérations du corpus; aucune nouveauté historique affirmée.', 'SYNTHESIS_FAITHFUL','RESOLVED_BY_EXISTING_QUALIFICATION')]
